window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2e481772ff5da607"]={"versions": [{"id": "FIG-2e481772ff5da607", "releases": ["R4.0.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine Software-Architektur im Kontext der AUTOSAR Timing Extensions dar, die als Referenzbeispiel für das Auftreten komplexer Ereignisse (Occurrence Expression) dient. Es handelt sich um ein formales AUTOSAR-Komponentendiagramm, das eine atomare Software-Komponente (Atomic Software Component) mit ihrer Port-Schnittstelle und dem zugrunde liegenden Schnittstellentyp abbildet.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst:</p>\n<ul class=\"fig-list\">\n<li>Software-Komponente <code>SWC1</code>: Repräsentiert eine Anwendungs-Software-Komponente.</li>\n<li>Port-Prototyp <code>P1</code>: An der linken Kante von <code>SWC1</code> als Port-Rechteck mit Buchsensymbol (Receiver-Port) modelliert.</li>\n<li>Schnittstelle <code>IF1</code> mit dem Stereotyp <code>&lt;&lt;S/R Interface&gt;&gt;</code>: Definiert ein Sender/Receiver-Interface. Sie beinhaltet drei Datenelemente (VariableDataPrototypes):</li>\n<li><code>DE1: uint8</code></li>\n<li><code>DE2: uint8</code></li>\n<li><code>DE3: uint8</code></li>\n<li>Beziehung <code>isOfType</code>: Ein gerichteter Pfeil von Port <code>P1</code> zur Schnittstelle <code>IF1</code> spezifiziert, dass der Port <code>P1</code> vom Typ der Schnittstelle <code>IF1</code> ist.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Schaubild selbst beschreibt eine statische Struktur. Im Kontext des begleitenden Timing-Extensions-Szenarios dient diese Struktur dem Empfang von Daten: An Port <code>P1</code> treffen Werte für die Datenelemente <code>DE1</code>, <code>DE2</code> und <code>DE3</code> ein. An diesen Empfangsereignissen knüpfen atomare Timing-Ereignisse (<code>E1</code> für <code>DE1</code>, <code>E2</code> für <code>DE2</code>) sowie Datenwert-Abfragen (Wert von <code>DE3</code>) an, die über logische und temporale Ausdrücke zu einem komplexen Timing-Ereignis verknüpft werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung definiert die Voraussetzungen zur Spezifikation von Occurrence Expressions auf Port- und Interface-Ebene. Für Entwickler und Timing-Modellierer zeigt das Beispiel, dass ein Receiver-Port mehrere VariableDataPrototypes desselben Sender/Receiver-Interfaces empfangen kann und diese atomaren Datenflüsse als Basis für getrennte oder kombinierte Timing-Events sowie Wertbedingungen herangezogen werden können.</p>"}, {"id": "FIG-ae8f79e6f957aa4c", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine Software-Architektur im Kontext der AUTOSAR Timing Extensions dar, die als Referenzbeispiel für Occurrence Expressions dient. Es handelt sich um ein AUTOSAR-Softwarekomponentendiagramm in modernisierter Notation, das eine Software-Komponente mit ihren Ports und der Typisierung eines Empfangsports über ein Sender/Receiver-Interface spezifiziert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst:</p>\n<ul class=\"fig-list\">\n<li>Software-Komponente <code>SW-C #1</code>: Als farblich hervorgehobener Komponentenblock dargestellt.</li>\n<li><code>Required Port</code>: An der linken Kante als Port-Quadrat mit einwärts gerichtetem Dreieck modelliert (AUTOSAR-Notation für R-Port).</li>\n<li><code>Provided Port</code>: An der rechten Kante als Port-Quadrat mit auswärts gerichtetem Dreieck dargestellt (P-Port).</li>\n<li><code>Sender/Receiver Interface IF1</code>: Als Schnittstellenblock mit abgesetztem Kopfbereich modelliert. Enthält die VariableDataPrototypes:</li>\n<li><code>DE1 : uint8</code></li>\n<li><code>DE2 : uint8</code></li>\n<li><code>DE3 : uint8</code></li>\n<li>Abhängigkeit <code>«isOfType»</code>: Ein gestrichelter Pfeil verläuft vom <code>Required Port</code> zur Schnittstelle <code>Sender/Receiver Interface IF1</code> und deklariert die Schnittstellentypisierung des Eingangsports.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Schaubild selbst beschreibt eine statische Struktur. Im Kontext des begleitenden Timing-Extensions-Szenarios dient diese Struktur dem Empfang von Daten: An Port <code>P1</code> treffen Werte für die Datenelemente <code>DE1</code>, <code>DE2</code> und <code>DE3</code> ein. An diesen Empfangsereignissen knüpfen atomare Timing-Ereignisse (<code>E1</code> für <code>DE1</code>, <code>E2</code> für <code>DE2</code>) sowie Datenwert-Abfragen (Wert von <code>DE3</code>) an, die über logische und temporale Ausdrücke zu einem komplexen Timing-Ereignis verknüpft werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert die standardkonforme AUTOSAR-Portmodellierung für Timing-Analysen. Entwickler müssen beachten, dass Timing-Expressions sowohl auf die strukturellen Ports (<code>Required Port</code>) als auch auf die im typisierenden Interface definierten Datenelemente (<code>DE1</code>, <code>DE2</code>, <code>DE3</code>) referenzieren. Der dargestellte <code>Provided Port</code> zeigt die Einbettung der Komponente in eine Verknüpfungskette, ist jedoch nicht weiter typisiert.</p>"}, {"id": "FIG-529e6ba67d958d29", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine Software-Architektur im Kontext der AUTOSAR Timing Extensions dar, die als Referenzbeispiel für Occurrence Expressions dient. Es handelt sich um ein AUTOSAR-Softwarekomponentendiagramm in modernisierter Notation, das eine Software-Komponente mit ihren Ports und der Typisierung eines Empfangsports über ein Sender/Receiver-Interface spezifiziert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst:</p>\n<ul class=\"fig-list\">\n<li>Software-Komponente <code>SW-C #1</code>: Als farblich hervorgehobener Komponentenblock dargestellt.</li>\n<li><code>Required Port</code>: An der linken Kante als Port-Quadrat mit einwärts gerichtetem Dreieck modelliert (AUTOSAR-Notation für R-Port).</li>\n<li><code>Provided Port</code>: An der rechten Kante als Port-Quadrat mit auswärts gerichtetem Dreieck dargestellt (P-Port).</li>\n<li><code>Sender/Receiver Interface IF1</code>: Als Schnittstellenblock mit abgesetztem Kopfbereich modelliert. Enthält die VariableDataPrototypes:</li>\n<li><code>DE1 : uint8</code></li>\n<li><code>DE2 : uint8</code></li>\n<li><code>DE3 : uint8</code></li>\n<li>Abhängigkeit <code>«isOfType»</code>: Ein gestrichelter Pfeil verläuft vom <code>Required Port</code> zur Schnittstelle <code>Sender/Receiver Interface IF1</code> und deklariert die Schnittstellentypisierung des Eingangsports.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Schaubild selbst beschreibt eine statische Struktur. Im Kontext des begleitenden Timing-Extensions-Szenarios dient diese Struktur dem Empfang von Daten: An Port <code>P1</code> treffen Werte für die Datenelemente <code>DE1</code>, <code>DE2</code> und <code>DE3</code> ein. An diesen Empfangsereignissen knüpfen atomare Timing-Ereignisse (<code>E1</code> für <code>DE1</code>, <code>E2</code> für <code>DE2</code>) sowie Datenwert-Abfragen (Wert von <code>DE3</code>) an, die über logische und temporale Ausdrücke zu einem komplexen Timing-Ereignis verknüpft werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert die standardkonforme AUTOSAR-Portmodellierung für Timing-Analysen. Entwickler müssen beachten, dass Timing-Expressions sowohl auf die strukturellen Ports (<code>Required Port</code>) als auch auf die im typisierenden Interface definierten Datenelemente (<code>DE1</code>, <code>DE2</code>, <code>DE3</code>) referenzieren. Der dargestellte <code>Provided Port</code> zeigt die Einbettung der Komponente in eine Verknüpfungskette, ist jedoch nicht weiter typisiert.</p>"}, {"id": "FIG-b74f8d22c9e58e69", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine Software-Architektur im Kontext der AUTOSAR Timing Extensions dar, die als Referenzbeispiel für Occurrence Expressions dient. Es handelt sich um ein AUTOSAR-Softwarekomponentendiagramm in modernisierter Notation, das eine Software-Komponente mit ihren Ports und der Typisierung eines Empfangsports über ein Sender/Receiver-Interface spezifiziert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst:</p>\n<ul class=\"fig-list\">\n<li>Software-Komponente <code>SW-C #1</code>: Als farblich hervorgehobener Komponentenblock dargestellt.</li>\n<li><code>Required Port</code>: An der linken Kante als Port-Quadrat mit einwärts gerichtetem Dreieck modelliert (AUTOSAR-Notation für R-Port).</li>\n<li><code>Provided Port</code>: An der rechten Kante als Port-Quadrat mit auswärts gerichtetem Dreieck dargestellt (P-Port).</li>\n<li><code>Sender/Receiver Interface IF1</code>: Als Schnittstellenblock mit abgesetztem Kopfbereich modelliert. Enthält die VariableDataPrototypes:</li>\n<li><code>DE1 : uint8</code></li>\n<li><code>DE2 : uint8</code></li>\n<li><code>DE3 : uint8</code></li>\n<li>Abhängigkeit <code>«isOfType»</code>: Ein gestrichelter Pfeil verläuft vom <code>Required Port</code> zur Schnittstelle <code>Sender/Receiver Interface IF1</code> und deklariert die Schnittstellentypisierung des Eingangsports.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Schaubild selbst beschreibt eine statische Struktur. Im Kontext des begleitenden Timing-Extensions-Szenarios dient diese Struktur dem Empfang von Daten: An Port <code>P1</code> treffen Werte für die Datenelemente <code>DE1</code>, <code>DE2</code> und <code>DE3</code> ein. An diesen Empfangsereignissen knüpfen atomare Timing-Ereignisse (<code>E1</code> für <code>DE1</code>, <code>E2</code> für <code>DE2</code>) sowie Datenwert-Abfragen (Wert von <code>DE3</code>) an, die über logische und temporale Ausdrücke zu einem komplexen Timing-Ereignis verknüpft werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert die standardkonforme AUTOSAR-Portmodellierung für Timing-Analysen. Entwickler müssen beachten, dass Timing-Expressions sowohl auf die strukturellen Ports (<code>Required Port</code>) als auch auf die im typisierenden Interface definierten Datenelemente (<code>DE1</code>, <code>DE2</code>, <code>DE3</code>) referenzieren. Der dargestellte <code>Provided Port</code> zeigt die Einbettung der Komponente in eine Verknüpfungskette, ist jedoch nicht weiter typisiert.</p>"}], "trans": [{"from": "FIG-2e481772ff5da607", "to": "FIG-ae8f79e6f957aa4c", "fr": "R4.1.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Software-Komponente: Umbenennung von <code>SWC1</code> in <code>SW-C #1</code>.</li>\n<li>Ports der Komponente: Umstellung von formaler Port-Bezeichnung <code>P1</code> mit Buchsensymbol auf AUTOSAR-Standard-Portsymbole (Quadrate mit Pfeil); der linke Port ist nun als <code>Required Port</code> beschriftet, rechts wurde ein nicht näher benannter <code>Provided Port</code> ergänzt.</li>\n<li>Schnittstellenbezeichnung: Stereotyp von <code>&lt;&lt;S/R Interface&gt;&gt;</code> zu <code>Sender/Receiver Interface</code> geändert; Trennlinie und Tabellenlayout der Interface-Box modernisiert.</li>\n<li>Typisierungsbeziehung: Die Abhängigkeit <code>isOfType</code> wird nun als gestrichelter Pfeil mit Guillemets <code>«isOfType»</code> dargestellt und verläuft vom Required Port zur Interface-Box.</li>\n<li>Attributschreibweise im Interface: Leerzeichen vor dem Doppelpunkt eingefügt (<code>DE1 : uint8</code>, <code>DE2 : uint8</code>, <code>DE3 : uint8</code>).</li>\n<li>Gesamtes Diagrammlayout von Querformat auf Hochformat umgestellt und farblich hinterlegt (Komponente bläulich, Schnittstellenkopf grau).</li>\n</ul>"}, {"from": "FIG-ae8f79e6f957aa4c", "to": "FIG-529e6ba67d958d29", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-529e6ba67d958d29", "to": "FIG-b74f8d22c9e58e69", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
